import random

def compute_A(a):
    n = len(a)
    sum_val = 0
    for x in range(n):
        prod = 1
        for y in range(n):
            if x == y:
                continue
            prod *= (a[x] * a[y] - 1) / (a[x] - a[y])
        sum_val += prod
    return sum_val

for i in range(1, 11):
    a = [random.uniform(3**k, 3**(k+1)) for k in range(1, i+2)]
    print(f"i={i}: {compute_A(a)}")

