import random
from sympy import Rational

def compute_A_sympy(a):
    n = len(a)
    sum_val = 0
    for x in range(n):
        prod = 1
        for y in range(n):
            if x == y:
                continue
            prod *= (a[x] * a[y] - 1) / (a[x] - a[y])
        sum_val += prod
    return sum_val

for i in [1, 2, 3, 4]:
    a = [Rational(random.randint(3**k + 1, 3**(k+1) - 1), 1) for k in range(1, i+2)]
    print(f"i={i}: {compute_A_sympy(a)}")
